383	    };
384	    return () => handleListProjects(ledgerRoot, params);
385	  }
386	
387	  // @deprecated — Use GET /api/projects/:repo/:slug/plan instead.
388	  // This non-namespaced route is retained for backward compatibility and will be
389	  // removed in the next major version.
390	  // GET /api/projects/:slug/plan
391	  if (
392	    method === 'GET' &&
393	    rest.length === 3 &&
394	    rest[0] === 'projects' &&
395	    rest[2] === 'plan'
396	  ) {
397	    const slug = rest[1]!;
398	    return () => handleGetPlanDocument(ledgerRoot, slug);
399	  }
400	
401	  // @deprecated — Use GET /api/projects/:repo/:slug/synthesis instead.
402	  // This non-namespaced route is retained for backward compatibility and will be
403	  // removed in the next major version.
404	  // GET /api/projects/:slug/synthesis
405	  if (
406	    method === 'GET' &&
407	    rest.length === 3 &&
408	    rest[0] === 'projects' &&
409	    rest[2] === 'synthesis'
410	  ) {
411	    const slug = rest[1]!;
412	    return () => handleGetSynthesisDocument(ledgerRoot, slug);
413	  }
414	
415	  // @deprecated — Use GET /api/projects/:repo/:slug/health instead.
416	  // This non-namespaced route is retained for backward compatibility and will be
417	  // removed in the next major version.
418	  // GET /api/projects/:slug/health
419	  if (
420	    method === 'GET' &&
