1317	
1318	async function serveStatic(
1319	  req: IncomingMessage,
1320	  res: ServerResponse,
1321	  port: number
1322	): Promise<void> {
1323	  const urlPath = (req.url ?? '/').split('?')[0]!;
1324	  const filePath =
1325	    urlPath === '/' ? join(PUBLIC_DIR, 'index.html') : join(PUBLIC_DIR, urlPath.slice(1));
1326	
1327	  // Security: prevent path traversal outside PUBLIC_DIR
1328	  const resolved = resolve(filePath);
1329	  if (!resolved.startsWith(PUBLIC_DIR)) {
1330	    sendError(res, 404, 'NOT_FOUND', 'Not found.', port);
1331	    return;
1332	  }
1333	
1334	  const ext = extname(filePath);
1335	  const mimeType = MIME_TYPES[ext] ?? 'application/octet-stream';
1336	
1337	  try {
1338	    const content = await readFile(filePath);
1339	    res.writeHead(200, {
1340	      'Content-Type': mimeType,
1341	      'Content-Length': content.length,
1342	      'Cache-Control': 'no-store',
1343	      ...corsHeaders(port),
1344	      ...securityHeaders(),
1345	    });
1346	    res.end(content);
1347	  } catch {
1348	    sendError(res, 404, 'NOT_FOUND', 'Not found.', port);
1349	  }
1350	}
